SELECT
WHERE cs.consult_type = 'DOCTOR'
AND cs.doctor_id = #{userId}
AND cs.resident_id = #{userId}
AND EXISTS (SELECT 1 FROM consult_message m WHERE m.session_id = cs.id)
ORDER BY COALESCE(lastMessageAt, cs.created_at) DESC, cs.id DESC

SELECT COUNT(DISTINCT cs.id) AS sessionCount,
       COUNT(*)              AS messageCount
FROM consult_message m
         JOIN consult_session cs ON cs.id = m.session_id
WHERE cs.consult_type = 'DOCTOR'
  AND cs.status = 'OPEN'
  AND m.read_at IS NULL
  AND m.sender <> #{mySender}


        AND cs.doctor_id = #{userId}


        AND cs.resident_id = #{userId}
